<?php
require_once __DIR__.'/functions.php';require_login();$pdo=db();$me=(int)user()['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$to=(int)($_POST['to']??0);$message=trim($_POST['message']??'');$allowed=$pdo->prepare("SELECT id FROM users WHERE id=? AND id<>? AND role IN('buyer','moderator','admin') LIMIT 1");$allowed->execute([$to,$me]);if($message&&$allowed->fetch())$pdo->prepare("INSERT INTO messages(sender_id,receiver_id,message) VALUES(?,?,?)")->execute([$me,$to,$message]);redirect('chat.php?user='.$to);}
$users=$pdo->prepare("SELECT DISTINCT u.id,u.name,u.role FROM users u JOIN messages m ON(m.sender_id=u.id OR m.receiver_id=u.id) WHERE u.id<>? AND u.role IN('buyer','moderator','admin') ORDER BY u.name");$users->execute([$me]);$users=$users->fetchAll();
$to=(int)($_GET['user']??($users[0]['id']??0));$target=null;if($to){$s=$pdo->prepare("SELECT id,name,role FROM users WHERE id=? AND id<>? AND role IN('buyer','moderator','admin')");$s->execute([$to,$me]);$target=$s->fetch();}
$msgs=[];if($target){$s=$pdo->prepare("SELECT m.*,u.name sender_name FROM messages m JOIN users u ON u.id=m.sender_id WHERE (sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?) ORDER BY m.created_at");$s->execute([$me,$to,$to,$me]);$msgs=$s->fetchAll();}
$title='Messages';include __DIR__.'/partials/header.php';?>
<section class="page"><div class="container"><div class="panel chat"><div class="chat-list"><h3 style="padding:0 14px">Conversations</h3><?php foreach($users as $u):?><a class="chat-user <?=($u['id']===$to?'active':'')?>" href="chat.php?user=<?=$u['id']?>"><b><?=e($u['name'])?></b><br><small class="muted"><?=e(ucfirst($u['role']))?></small></a><?php endforeach;?><?php if(!$users):?><p class="muted" style="padding:14px">No conversations yet.</p><?php endif;?></div><div class="chat-box"><?php if($target):?><div style="padding:15px;border-bottom:1px solid var(--line)"><b><?=e($target['name'])?></b> · <?=e(ucfirst($target['role']))?></div><div class="messages"><?php foreach($msgs as $m):?><div class="msg <?=($m['sender_id']===$me?'mine':'')?>"><?=nl2br(e($m['message']))?><small><?=e($m['sender_name'])?> · <?=e($m['created_at'])?></small></div><?php endforeach;?></div><form class="chat-form" method="post"><?=csrf_field()?><input type="hidden" name="to" value="<?=$to?>"><input name="message" placeholder="Write a message..." required><button class="btn btn-primary">Send</button></form><?php else:?><div style="padding:30px"><h2>Messages</h2><p class="muted">Select a conversation to start chatting.</p></div><?php endif;?></div></div></div></section><?php include __DIR__.'/partials/footer.php';?>
